-- Written to be re-runnable: production applies each statement on its own, so a run
-- interrupted part way must be able to start again from the top.
-- The expiry date of a document as typed by its owner (or read from a passport's lines): one new
-- append-only table, nothing existing is touched. The table was generated by drizzle-kit and made
-- re-runnable here. Until this runs the code finds the table missing, offers no way to type a date,
-- and every page reads exactly as before. created_at defaults to clock_timestamp() (the moment of
-- insertion) because the newest entry decides where the saved date came from. Postgres keeps only
-- the first 63 characters of a name, so the foreign key guards compare that much.
CREATE TABLE IF NOT EXISTS "document_expiry_entries" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"document_id" uuid NOT NULL,
	"expires_on" date,
	"source" text NOT NULL,
	"mirrored" boolean DEFAULT false NOT NULL,
	"entered_by_account_id" uuid,
	"created_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
	CONSTRAINT "document_expiry_entries_source_known" CHECK ("document_expiry_entries"."source" in ('TYPED', 'READ')),
	CONSTRAINT "document_expiry_entries_mirrored_typed" CHECK (not "document_expiry_entries"."mirrored" or ("document_expiry_entries"."source" = 'TYPED' and "document_expiry_entries"."expires_on" is not null)),
	CONSTRAINT "document_expiry_entries_read_has_date" CHECK ("document_expiry_entries"."source" = 'TYPED' or "document_expiry_entries"."expires_on" is not null)
);
--> statement-breakpoint
DO $fk$ BEGIN
	IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = left('document_expiry_entries_document_id_documents_id_fk', 63)) THEN
		ALTER TABLE "document_expiry_entries" ADD CONSTRAINT "document_expiry_entries_document_id_documents_id_fk" FOREIGN KEY ("document_id") REFERENCES "public"."documents"("id") ON DELETE cascade ON UPDATE no action;
	END IF;
	IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = left('document_expiry_entries_entered_by_account_id_accounts_id_fk', 63)) THEN
		ALTER TABLE "document_expiry_entries" ADD CONSTRAINT "document_expiry_entries_entered_by_account_id_accounts_id_fk" FOREIGN KEY ("entered_by_account_id") REFERENCES "public"."accounts"("id") ON DELETE set null ON UPDATE no action;
	END IF;
END $fk$;
--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "document_expiry_entries_document_idx" ON "document_expiry_entries" USING btree ("document_id","created_at");
--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "document_expiry_entries_entered_by_idx" ON "document_expiry_entries" USING btree ("entered_by_account_id");
